        stack=[(i,j)]; seen.add((i,j)); cells=[]
        while stack:
          r,c=stack.pop(); cells.append((r,c))
          for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and g[nr][nc] and (nr,nc) not in seen:
              seen.add((nr,nc)); stack.append((nr,nc))
        r0=min(r for r,c in cells); r1=max(r for r,c in cells); c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        layers=[]; box={(r,c) for r,c in cells}
        while box:
          edge={(r,c) for r,c in box if r==r0 or r==r1 or c==c0 or c==c1}
          for x in edge:
            v=g[x[0]][x[1]]
            if v not in layers: layers.append(v)
